-- Catálogo de demonstração da Renova Retífica de Motores.
-- Substitui os produtos/categorias genéricos do V011 (compressor, chave de impacto...)
-- por peças, óleos, motores e serviços de retífica (docs/13 — M17).
-- Sem imagens: o ProdutoCard mostra placeholder.
-- Serviços usam preço de referência ("a partir de"); o valor final sai após avaliação.

-- ---------------------------------------------------------------------------
-- 1. Remove o seed genérico do V011 (só por slug, sem tocar no que o admin criou)
-- ---------------------------------------------------------------------------
DELETE FROM compra
 WHERE produto_id IN (SELECT id FROM produto WHERE slug IN (
     'compressor-industrial-20hp', 'motor-eletrico-trifasico-5cv', 'oleo-lubrificante-iso-68-20l',
     'rolamento-6205-zz', 'correia-industrial-a-60', 'chave-impacto-pneumatica-1-2'));

DELETE FROM produto WHERE slug IN (
    'compressor-industrial-20hp', 'motor-eletrico-trifasico-5cv', 'oleo-lubrificante-iso-68-20l',
    'rolamento-6205-zz', 'correia-industrial-a-60', 'chave-impacto-pneumatica-1-2');

-- Categoria com produto criado à mão fica (FK RESTRICT bloquearia a migration).
DELETE FROM categoria c
 WHERE c.slug IN ('equipamentos', 'insumos', 'pecas', 'ferramentas')
   AND NOT EXISTS (SELECT 1 FROM produto p WHERE p.categoria_id = c.id)
   AND NOT EXISTS (SELECT 1 FROM categoria f WHERE f.parent_id = c.id);

-- ---------------------------------------------------------------------------
-- 2. Categorias: raiz = cards de venda do /sobre + Serviços
-- ---------------------------------------------------------------------------
INSERT INTO categoria (nome, slug, descricao) VALUES
    ('Peças de motor',                'pecas-de-motor',        'Peças de reposição para motores a gasolina, álcool, flex e diesel'),
    ('Óleos e lubrificantes',         'oleos-e-lubrificantes', 'Óleos de motor, filtros, aditivos e fluidos'),
    ('Motores retificados',           'motores-retificados',   'Motores recuperados na nossa oficina, montados e testados'),
    ('Meio motor e usados revisados', 'meio-motor-e-usados',   'Meio motor e motores usados revisados antes da venda'),
    ('Serviços de retífica',          'servicos-de-retifica',  'Retífica feita na nossa oficina, com preço de referência');

INSERT INTO categoria (nome, slug, parent_id, descricao)
SELECT v.nome, v.slug, (SELECT id FROM categoria WHERE slug = v.pai), v.descricao
FROM (VALUES
    ('pecas-de-motor',        'Pistões e anéis',               'pistoes-e-aneis',               'Jogos de pistões, pinos e anéis'),
    ('pecas-de-motor',        'Bronzinas e arruelas',          'bronzinas-e-arruelas',          'Bronzinas de mancal e de biela, arruelas de encosto'),
    ('pecas-de-motor',        'Juntas e retentores',           'juntas-e-retentores',           'Juntas de cabeçote, jogos de juntas e retentores'),
    ('pecas-de-motor',        'Cabeçote e válvulas',           'cabecote-e-valvulas',           'Válvulas, guias, tuchos e comandos'),
    ('pecas-de-motor',        'Distribuição',                  'distribuicao',                  'Kits de correia dentada, tensores e correntes'),
    ('pecas-de-motor',        'Bombas de óleo e água',         'bombas-de-oleo-e-agua',         'Bombas de óleo e bombas d''água'),
    ('pecas-de-motor',        'Peças diesel',                  'pecas-diesel',                  'Kits e peças para motores diesel de caminhões e máquinas'),
    ('oleos-e-lubrificantes', 'Óleos para gasolina e flex',    'oleos-gasolina-e-flex',         'Óleos de motor para carros de passeio e motores de popa'),
    ('oleos-e-lubrificantes', 'Óleos diesel',                  'oleos-diesel',                  'Óleos para motores diesel leves e pesados'),
    ('oleos-e-lubrificantes', 'Filtros',                       'filtros',                       'Filtros de óleo, combustível e ar'),
    ('oleos-e-lubrificantes', 'Aditivos e fluidos',            'aditivos-e-fluidos',            'Aditivos de radiador, limpeza e montagem'),
    ('servicos-de-retifica',  'Cabeçote',                      'servicos-cabecote',             'Retífica, plaina, teste e troca de guias e sedes'),
    ('servicos-de-retifica',  'Virabrequim e bielas',          'servicos-virabrequim-e-bielas', 'Retífica de colos, moentes e bielas'),
    ('servicos-de-retifica',  'Bloco do motor',                'servicos-bloco',                'Brunimento, encamisamento, mancais e plaina'),
    ('servicos-de-retifica',  'Retífica completa e montagem',  'servicos-retifica-completa',    'Retífica completa e montagem do motor')
) AS v(pai, nome, slug, descricao);

-- ---------------------------------------------------------------------------
-- 3. Produtos e serviços
-- Subselect de categoria (em vez de JOIN): slug errado falha no NOT NULL em vez de sumir.
-- Datas espalhadas nos últimos 240 dias, determinísticas pelo slug.
-- ---------------------------------------------------------------------------
INSERT INTO produto (nome, slug, descricao, preco, categoria_id, ficha_tecnica, created_at, updated_at)
SELECT v.nome, v.slug, v.descricao, v.preco,
       (SELECT id FROM categoria WHERE slug = v.cat),
       v.ficha::jsonb,
       now() - make_interval(days => d.criado),
       now() - make_interval(days => d.criado * d.pct / 100)
FROM (VALUES
